package com.matejpcs.netflared;
import com.mojang.brigadier.CommandDispatcher;import com.mojang.brigadier.arguments.StringArgumentType;import net.minecraft.commands.*;import net.minecraft.network.chat.Component;import net.minecraft.server.MinecraftServer;import net.minecraftforge.event.RegisterCommandsEvent;import net.minecraftforge.event.server.ServerStartedEvent;import net.minecraftforge.event.server.ServerStoppingEvent;import net.minecraftforge.fml.common.Mod;import java.nio.file.Path;
@Mod("netflared")public final class NetflaredForge{private NetflaredService service;private MinecraftServer server;public NetflaredForge(){RegisterCommandsEvent.BUS.addListener(this::commands);ServerStartedEvent.BUS.addListener(this::started);ServerStoppingEvent.BUS.addListener(this::stopping);}
public void commands(RegisterCommandsEvent e){CommandDispatcher<CommandSourceStack>d=e.getDispatcher();d.register(Commands.literal("netflared").requires(source -> source.permissions().hasPermission(new net.minecraft.server.permissions.Permission.HasCommandLevel(net.minecraft.server.permissions.PermissionLevel.byId(4)))).executes(x->{run(x.getSource(),new String[0]);return 1;}).then(Commands.literal("status").executes(x->{run(x.getSource(),new String[]{"status"});return 1;})).then(Commands.literal("info").executes(x->{run(x.getSource(),new String[]{"info"});return 1;})).then(Commands.literal("connect").executes(x->{run(x.getSource(),new String[]{"connect"});return 1;})).then(Commands.literal("disconnect").executes(x->{run(x.getSource(),new String[]{"disconnect"});return 1;})).then(Commands.literal("reload").executes(x->{run(x.getSource(),new String[]{"reload"});return 1;})).then(Commands.literal("reset").executes(x->{run(x.getSource(),new String[]{"reset"});return 1;})).then(Commands.literal("setup").then(Commands.argument("token",StringArgumentType.greedyString()).executes(x->{run(x.getSource(),new String[]{"setup",StringArgumentType.getString(x,"token")});return 1;}))));}
public void started(ServerStartedEvent e){server=e.getServer();try{service=new NetflaredService(Path.of("config","netflared"),()->new NetflaredService.ServerInfo(server.getPort(),"forge"),server::execute);service.autoConnect();}catch(Exception x){server.sendSystemMessage(Component.literal("Netflared failed to initialize: "+x.getMessage()));}}
public void stopping(ServerStoppingEvent e){if(service!=null)service.shutdown();}private void run(CommandSourceStack s,String[]a){if(service==null){s.sendFailure(Component.literal("Netflared is not initialized."));return;}service.handle(new NetflaredService.Sender(){public boolean admin(){return true;}public void send(String m){s.sendSystemMessage(Component.literal(m.replaceAll("§.","")));}},a);}}
